<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo Cypress Testing</title><link rel="stylesheet" href="demo-style.css?v=4"><style>.status{font-weight:900}.ok{color:#2f7d5c}.fail{color:#a64d57}.metric strong{font-size:2.3rem;display:block}.log{font-family:ui-monospace,Consolas,monospace;font-size:.9rem}</style></head><body><nav class="demo-nav"><div class="demo-nav-inner"><a class="brand" href="../index.php#proyectos">← Volver al portafolio</a><a class="btn primary" href="#">GitHub pendiente</a></div></nav><main class="wrap"><section class="hero"><div><span class="kicker">QA Automation</span><h1>Cypress Testing</h1><p>Dashboard demo para visualizar pruebas automatizadas: casos positivos, negativos y de borde.</p></div><div class="panel grid grid-3"><div class="card metric"><strong id="total">15</strong><span>Total</span></div><div class="card metric"><strong id="ok">12</strong><span>OK</span></div><div class="card metric"><strong id="fix">3</strong><span>Fix</span></div></div></section><section class="panel"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><h2>Suite de pruebas</h2><button class="btn primary" onclick="run()">Ejecutar demo</button></div><div id="logs" class="grid"></div></section></main><script>const cases=['Login válido','Formulario contacto','Filtro de búsqueda','Compra simulada','Validación email'];function run(){logs.innerHTML='';cases.forEach((x,i)=>setTimeout(()=>{let d=document.createElement('div');d.className='card log';d.innerHTML='✓ '+x+' <span class="status ok">PASSED</span>';logs.appendChild(d)},i*250))}run();</script></body></html>
